diff --git a/libarchive/archive_read_support_format_rar5.c b/libarchive/archive_read_support_format_rar5.c
index f9a2327..e7a5321 100644
--- a/libarchive/archive_read_support_format_rar5.c
+++ b/libarchive/archive_read_support_format_rar5.c
@@ -1565,7 +1565,7 @@ static int parse_file_extra_owner(struct archive_read* a,
 	size_t name_len = 0;
 	size_t name_size = 0;
 	size_t varint_len = 0;
-	char namebuf[OWNER_MAXNAMELEN];
+	char namebuf[OWNER_MAXNAMELEN + 1];
 	const uint8_t* p;

 	if(!read_var(a, &flags, &value_size))
@@ -1594,8 +1594,8 @@ static int parse_file_extra_owner(struct archive_read* a,
 		if(!read_ahead(a, name_size, &p))
 			return ARCHIVE_EOF;

-		if (name_size >= OWNER_MAXNAMELEN) {
-			name_len = OWNER_MAXNAMELEN - 1;
+		if (name_size > OWNER_MAXNAMELEN) {
+			name_len = OWNER_MAXNAMELEN;
 		} else {
 			name_len = name_size;
 		}
@@ -1624,8 +1624,8 @@ static int parse_file_extra_owner(struct archive_read* a,
 		if(!read_ahead(a, name_size, &p))
 			return ARCHIVE_EOF;

-		if (name_size >= OWNER_MAXNAMELEN) {
-			name_len = OWNER_MAXNAMELEN - 1;
+		if (name_size > OWNER_MAXNAMELEN) {
+			name_len = OWNER_MAXNAMELEN;
 		} else {
 			name_len = name_size;
 		}

